macro_rules! Error {
    () => {
        # [doc = " Error returned when executing/parsing `cargo metadata` fails."] # [doc = ""] # [doc = " # Note about Backtraces"] # [doc = ""] # [doc = " This error type does not contain backtraces, but each error variant"] # [doc = " comes from _one_ specific place, so it's not really needed for the"] # [doc = " inside of this crate. If you need a backtrace down to, but not inside"] # [doc = " of, a failed call of `cargo_metadata` you can do one of multiple thinks:"] # [doc = ""] # [doc = " 1. Convert it to a `failure::Error` (possible using the `?` operator),"] # [doc = "    which is similar to a `Box<::std::error::Error + 'static + Send  + Sync>`."] # [doc = " 2. Have appropriate variants in your own error type. E.g. you could wrap"] # [doc = "    a `failure::Context<Error>` or add a `failure::Backtrace` field (which"] # [doc = "    is empty if `RUST_BACKTRACE` is not set, so it's simple to use)."] # [doc = " 3. You still can place a failure based error into a `error_chain` if you"] # [doc = "    really want to. (Either through foreign_links or by making it a field"] # [doc = "    value of a `ErrorKind` variant)."] # [doc = ""] # [derive (Debug , thiserror :: Error)] pub enum Error { # [doc = " Error during execution of `cargo metadata`"] # [error ("`cargo metadata` exited with an error: {stderr}")] CargoMetadata { # [doc = " stderr returned by the `cargo metadata` command"] stderr : String , } , # [doc = " IO Error during execution of `cargo metadata`"] # [error ("failed to start `cargo metadata`: {0}")] Io (# [from] io :: Error) , # [doc = " Output of `cargo metadata` was not valid utf8"] # [error ("cannot convert the stdout of `cargo metadata`: {0}")] Utf8 (# [from] Utf8Error) , # [doc = " Error output of `cargo metadata` was not valid utf8"] # [error ("cannot convert the stderr of `cargo metadata`: {0}")] ErrUtf8 (# [from] FromUtf8Error) , # [doc = " Deserialization error (structure of json did not match expected structure)"] # [error ("failed to interpret `cargo metadata`'s json: {0}")] Json (# [from] :: serde_json :: Error) , # [doc = " The output did not contain any json"] # [error ("could not find any json in the output of `cargo metadata`")] NoJson , }
    };
}

Error!()